import { defineConfig } from "@playwright/test";
import config from "../../playwright.config";
import { fileURLToPath } from "node:url";
export default defineConfig({
  ...config,
  testDir: "./trace-probe",
  webServer: { ...config.webServer, cwd: fileURLToPath(new URL("../../", import.meta.url)) },
  projects: [{ name: "native-diagnostics" }],
  reporter: "list",
  outputDir: "./trace-probe-results",
  use: {
    ...config.use,
    javaScriptEnabled: false,
    viewport: { width: 390, height: 844 },
  },
});

nativeProbe.test:
import { test, expect } from "../../../tests/studio/fixtures";
test("owned static-page failure retains its native trace", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByRole("heading", { level: 1 })).toHaveText(
    "Make your console worth opening.",
  );
  throw new Error("Intentional native diagnostics probe");
});
